#!/usr/bin/env bash
# Downloads every image/PDF used by the site from the old Squarespace CDN.
# Re-run any time; existing files are skipped. Usage: bash scripts/fetch-assets.sh
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p assets/{logo,logos,headshots,photos,edge,docs}
get() { # url dest
  if [ -s "assets/$2" ]; then echo "skip  $2"; return; fi
  curl -fsSL -H 'Accept: image/png,image/jpeg,image/*;q=0.8,*/*;q=0.5' "$1" -o "assets/$2" && echo "saved $2" || echo "FAILED $2  <- $1"
}

